/* Original, AI-assisted (Codex), LGPL-2.1-or-later. Public API MEASURE.
 * No Windows expectations: creation failures are observations, not passes. */
#define COBJMACROS
#include <windows.h>
#include <oleauto.h>
#include <stdio.h>
#include <string.h>
#include <stdlib.h>

static unsigned errors;

/* Layout checked against Wine 11.20's public MSFT reader/format declarations.
 * Only call this on the temporary library generated by this program. No
 * file supplied by the user, OS, or a vendor is opened here. */
static DWORD word32(const BYTE *p)
{
    return (DWORD)p[0] | (DWORD)p[1] << 8 | (DWORD)p[2] << 16 | (DWORD)p[3] << 24;
}

static int region(DWORD offset, DWORD length, DWORD size)
{
    return offset <= size && length <= size - offset;
}

static int audit_file(const WCHAR *path, int encoded_fixture)
{
    HANDLE file = INVALID_HANDLE_VALUE;
    BYTE *bytes = NULL;
    DWORD size, read, directory, types, desc, desc_size, arrays, arrays_size;
    DWORD pointer32 = 0, pointer64 = 0, array32 = 0, array64 = 0;
    DWORD element32 = 0, element64 = 0;
    DWORD pointer_signed = 0, array_signed = 0, element_signed = 0;
    int success = 0;
    file = CreateFileW(path, GENERIC_READ | (encoded_fixture ? GENERIC_WRITE : 0),
                       0, NULL, OPEN_EXISTING, FILE_ATTRIBUTE_NORMAL, NULL);
    if (file == INVALID_HANDLE_VALUE) goto done;
    size = GetFileSize(file, NULL);
    if (size < 0x54 || size > 32 * 1024 * 1024) goto done;
    bytes = malloc(size);
    if (!bytes || !ReadFile(file, bytes, size, &read, NULL) || read != size) goto done;
    if (memcmp(bytes, "MSFT", 4)) goto done;
    types = word32(bytes + 0x20);
    if (types > (size - 0x54) / 4) goto done;
    directory = 0x54 + types * 4;
    if (word32(bytes + 0x14) & 0x100) directory += 4;
    if (!region(directory, 15 * 16, size)) goto done;
    desc = word32(bytes + directory + 9 * 16);
    desc_size = word32(bytes + directory + 9 * 16 + 4);
    arrays = word32(bytes + directory + 10 * 16);
    arrays_size = word32(bytes + directory + 10 * 16 + 4);
    if (!region(desc, desc_size, size) || desc_size % 8) goto done;
    /* Empty segments may use -1 as offset. */
    if (arrays_size && !region(arrays, arrays_size, size)) goto done;
    for (DWORD i = 0; i < desc_size; i += 8)
    {
        DWORD vt = word32(bytes + desc + i) & 0xffff;
        DWORD reference = word32(bytes + desc + i + 4);
        if ((vt == VT_PTR || vt == VT_SAFEARRAY) && !(reference & 0x80000000))
        {
            if (reference % 8 || !region(reference, 8, desc_size)) goto done;
            pointer32 += reference >= 0x8000;
            pointer64 += reference >= 0x10000;
            pointer_signed += !!(reference & 0x8000);
        }
        if (vt == VT_CARRAY)
        {
            DWORD element;
            if (!region(reference, 8, arrays_size)) goto done;
            array32 += reference >= 0x8000;
            array64 += reference >= 0x10000;
            array_signed += !!(reference & 0x8000);
            element = word32(bytes + arrays + reference);
            if (!(element & 0x80000000))
            {
                if (element % 8 || !region(element, 8, desc_size)) goto done;
                element32 += element >= 0x8000;
                element64 += element >= 0x10000;
                element_signed += !!(element & 0x8000);
            }
        }
    }
    printf("SERIAL types=%lu desc_bytes=%lu array_bytes=%lu ptr_ge8000=%lu ptr_ge10000=%lu "
           "array_ge8000=%lu array_ge10000=%lu element_ge8000=%lu element_ge10000=%lu\n",
           (unsigned long)types, (unsigned long)desc_size, (unsigned long)arrays_size,
           (unsigned long)pointer32, (unsigned long)pointer64, (unsigned long)array32,
           (unsigned long)array64, (unsigned long)element32, (unsigned long)element64);
    printf("SERIAL_SIGNED ptr_low_bit15=%lu array_low_bit15=%lu element_low_bit15=%lu\n",
           (unsigned long)pointer_signed, (unsigned long)array_signed, (unsigned long)element_signed);
    if (encoded_fixture)
    {
        DWORD written;
        if (types != 1 || desc_size != 8 ||
            (word32(bytes + desc) & 0xffff) != VT_PTR ||
            (word32(bytes + desc + 4) & 0xffff) != VT_I4 ||
            !(word32(bytes + desc + 4) & 0x80000000)) goto done;
        /* Change only the low 16-bit simple pointee of our PTR(I4) fixture.
         * Leave the native writer's high marker and all other bytes intact. */
        bytes[desc + 4] = 3;
        bytes[desc + 5] = 0x20;
        if (SetFilePointer(file, 0, NULL, FILE_BEGIN) == INVALID_SET_FILE_POINTER ||
            !WriteFile(file, bytes, size, &written, NULL) || written != size ||
            !FlushFileBuffers(file)) goto done;
        puts("FIXTURE changed_bytes=1 pointee_before=0003 pointee_after=2003");
    }
    success = 1;
done:
    free(bytes);
    if (file != INVALID_HANDLE_VALUE) CloseHandle(file);
    if (!success) { puts("ERROR synthetic_file_audit_or_edit"); errors++; }
    return success;
}
static int result(const char *op, HRESULT hr)
{
    printf("API op=%s hr=%08lx\n", op, (unsigned long)hr);
    if (FAILED(hr)) errors++;
    return SUCCEEDED(hr);
}

static void describe(const TYPEDESC *td, unsigned depth)
{
    printf("DESC depth=%u vt=%04x\n", depth, td->vt);
    if (depth == 8) { puts("LIMIT depth=8"); return; }
    if (td->vt == VT_PTR || td->vt == VT_SAFEARRAY)
    {
        if (td->lptdesc) describe(td->lptdesc, depth + 1);
        else { puts("ERROR null_pointee"); errors++; }
    }
    else if (td->vt == VT_CARRAY)
    {
        const ARRAYDESC *a = td->lpadesc;
        if (!a) { puts("ERROR null_array"); errors++; return; }
        printf("ARRAY dims=%u\n", a->cDims);
        for (unsigned i = 0; i < a->cDims && i < 4; i++)
            printf("BOUND index=%u count=%lu low=%ld\n", i,
                   (unsigned long)a->rgbounds[i].cElements, (long)a->rgbounds[i].lLbound);
        describe(&a->tdescElem, depth + 1);
    }
}

static void library(const char *label, TYPEDESC *desc, unsigned count, int encoded_fixture)
{
    WCHAR dir[MAX_PATH], path[MAX_PATH], name[40];
    ICreateTypeLib2 *create = NULL;
    ITypeLib *loaded = NULL;
    unsigned before = errors;
    DWORD path_length = GetTempPathW(MAX_PATH, dir);
    if (!path_length || path_length >= MAX_PATH || !GetTempFileNameW(dir, L"wbt", 0, path))
    { puts("ERROR tempfile"); errors++; return; }
    DeleteFileW(path);
    printf("CASE name=%s types=%u\n", label, count);
    if (!result("CreateTypeLib2", CreateTypeLib2(sizeof(void *) == 8 ? SYS_WIN64 : SYS_WIN32, path, &create))) goto done;
    if (!result("SetName", ICreateTypeLib2_SetName(create, L"WinumSyntheticTypes"))) goto done;
    for (unsigned i = 0; i < count; i++)
    {
        ICreateTypeInfo *type = NULL;
        HRESULT hr;
        swprintf(name, 40, L"Alias%u", i);
        hr = ICreateTypeLib2_CreateTypeInfo(create, name, TKIND_ALIAS, &type);
        if (FAILED(hr)) { result("CreateTypeInfo", hr); goto done; }
        if (count > 1)
        {
            /* Unique inner bounds prevent deduplication of the nested chain.
             * Both array-descriptor and type-descriptor tables grow. */
            ARRAYDESC inner = {0};
            ARRAYDESC outer = {0};
            TYPEDESC pointer;
            inner.tdescElem.vt = VT_I4;
            inner.cDims = outer.cDims = 1;
            inner.rgbounds[0].cElements = 2 + i;
            outer.rgbounds[0].cElements = 2;
            pointer.vt = VT_PTR;
            pointer.lptdesc = (TYPEDESC *)&(TYPEDESC){.lpadesc=&inner, .vt=VT_CARRAY};
            outer.tdescElem = pointer;
            TYPEDESC array = {.lpadesc=&outer, .vt=VT_CARRAY};
            TYPEDESC root = {.lptdesc=&array, .vt=VT_PTR};
            hr = ICreateTypeInfo_SetTypeDescAlias(type, &root);
        }
        else hr = ICreateTypeInfo_SetTypeDescAlias(type, desc);
        ICreateTypeInfo_Release(type);
        if (FAILED(hr)) { result("SetTypeDescAlias", hr); goto done; }
    }
    if (!result("SaveAllChanges", ICreateTypeLib2_SaveAllChanges(create))) goto done;
    ICreateTypeLib2_Release(create);
    create = NULL;
    if (!audit_file(path, encoded_fixture)) goto done;
    if (encoded_fixture)
    {
        WCHAR fresh[MAX_PATH];
        /* A different generated path avoids reusing the writer's cached
         * identity when asking the native loader to read edited bytes. */
        if (!GetTempFileNameW(dir, L"wbr", 0, fresh))
        { puts("ERROR fresh_load_path"); errors++; goto done; }
        if (!CopyFileW(path, fresh, FALSE))
        { DeleteFileW(fresh); puts("ERROR copy_fixture"); errors++; goto done; }
        if (!DeleteFileW(path)) { puts("ERROR original_fixture_cleanup"); errors++; }
        lstrcpyW(path, fresh);
        puts("FIXTURE fresh_load_path=1");
    }
    if (!result("LoadTypeLibEx", LoadTypeLibEx(path, REGKIND_NONE, &loaded))) goto done;
    printf("LIB types=%u\n", ITypeLib_GetTypeInfoCount(loaded));
    for (unsigned i = 0; i < count; i++)
    {
        ITypeInfo *type = NULL;
        TYPEATTR *attr = NULL;
        if (count > 1 && i != 0 && i != 1500 && i != 3000 && i != count - 1) continue;
        printf("TYPE index=%u\n", i);
        if (!result("GetTypeInfo", ITypeLib_GetTypeInfo(loaded, i, &type))) continue;
        if (result("GetTypeAttr", ITypeInfo_GetTypeAttr(type, &attr)))
        {
            printf("ATTR kind=%u\n", (unsigned)attr->typekind);
            describe(&attr->tdescAlias, 0);
            ITypeInfo_ReleaseTypeAttr(type, attr);
        }
        ITypeInfo_Release(type);
    }
done:
    if (loaded) ITypeLib_Release(loaded);
    if (create) ICreateTypeLib2_Release(create);
    if (!DeleteFileW(path) && GetLastError() != ERROR_FILE_NOT_FOUND)
    { puts("ERROR cleanup"); errors++; }
    printf("CASE_END name=%s api_errors=%u\n", label, errors - before);
}

int main(int argc, char **argv)
{
    TYPEDESC simple = {.vt=VT_I4}, encoded = {.vt=VT_ARRAY | VT_I4};
    TYPEDESC safe = {.lptdesc=&simple, .vt=VT_SAFEARRAY};
    TYPEDESC pointer = {.lptdesc=&simple, .vt=VT_PTR};
    HRESULT hr;
    int reader_only = argc == 2 && !strcmp(argv[1], "--reader-only");
    if (argc != 1 && !reader_only) return 2;
    SetErrorMode(SEM_FAILCRITICALERRORS | SEM_NOGPFAULTERRORBOX);
    hr = CoInitializeEx(NULL, COINIT_APARTMENTTHREADED);
    setvbuf(stdout, NULL, _IONBF, 0);
    printf("MEASURE schema=2 topic=typedesc bits=%u\n", (unsigned)(8 * sizeof(void *)));
    if (!result("CoInitializeEx", hr)) return 2;
    if (reader_only) library("reader_encoded_array_i4", &pointer, 1, 1);
    else
    {
        library("pointer_i4", &pointer, 1, 0);
        pointer.lptdesc = &encoded;
        library("pointer_encoded_array_i4", &pointer, 1, 0);
        pointer.lptdesc = &safe;
        library("pointer_safearray_i4", &pointer, 1, 0);
        library("large_nested_arrays", NULL, 5000, 0);
    }
    CoUninitialize();
    printf("SUMMARY api_errors=%u expectations=none\n", errors);
    return errors ? 2 : 0;
}
